const CSS="\n/* Layout: links Raumliste, rechts Editor des gewählten Raums, darunter Ausgabe; stapelt sich am Handy */\n:host{--bg:#F3F4F7;--panel:#FFFFFF;--fg:#141A26;--muted:#5E6878;--line:#DDE2EA;--accent:#D97706;--accent-soft:#FDF0DC;--ok:#15803D;--danger:#B42318;--field:#F7F8FA;\n--f-ui:\"Inter\",system-ui,-apple-system,\"Segoe UI\",Roboto,sans-serif;--f-mono:ui-monospace,\"Cascadia Mono\",Consolas,monospace;color-scheme:light}\n@media (prefers-color-scheme:dark){:host(:not([data-theme=\"light\"])){--bg:#0C1018;--panel:#151B26;--fg:#EDF1F7;--muted:#9AA6B8;--line:#273142;--accent:#F59E0B;--accent-soft:#2A2214;--ok:#4ADE80;--danger:#F87171;--field:#0F141D;color-scheme:dark}}\n:host([data-theme=\"dark\"]){--bg:#0C1018;--panel:#151B26;--fg:#EDF1F7;--muted:#9AA6B8;--line:#273142;--accent:#F59E0B;--accent-soft:#2A2214;--ok:#4ADE80;--danger:#F87171;--field:#0F141D;color-scheme:dark}\n:host{display:block;height:100%;overflow-y:auto;background:var(--bg);color:var(--fg);font-family:var(--f-ui);font-size:14px;line-height:1.4;-webkit-font-smoothing:antialiased}\n*{box-sizing:border-box}[hidden]{display:none!important}\n.wrap{max-width:1180px;margin:0 auto;padding-block:20px 40px;padding-left:max(16px,env(safe-area-inset-left,0px));padding-right:max(16px,env(safe-area-inset-right,0px));display:flex;flex-direction:column;gap:16px}\nheader{display:flex;flex-wrap:wrap;align-items:flex-end;justify-content:space-between;gap:12px}\nh1{font-size:22px;margin:0;text-wrap:balance} .sub{color:var(--muted);margin:4px 0 0}\n.grid{display:grid;grid-template-columns:300px minmax(0,1fr);gap:16px;align-items:start}\n@media (max-width:820px){.grid{grid-template-columns:1fr}}\n.panel{background:var(--panel);border:1px solid var(--line);border-radius:14px;padding:14px;min-width:0}\nh2{font-size:12px;letter-spacing:1.2px;text-transform:uppercase;color:var(--muted);margin:0 0 10px;font-weight:600}\n.rooms{display:flex;flex-direction:column;gap:6px}\n.room{display:flex;align-items:center;gap:8px;padding:8px 8px 8px 10px;border-radius:10px;border:1px solid transparent;cursor:pointer;background:var(--field)}\n.room:hover{border-color:var(--line)} .room.sel{border-color:var(--accent);background:var(--accent-soft)}\n.room .t{flex:1;min-width:0} .room b{display:block;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis} .room small{color:var(--muted)}\n.dots{display:inline-flex;gap:3px;vertical-align:middle;margin-left:4px}.dots i{width:7px;height:7px;border-radius:50%;background:var(--accent);display:inline-block}\n.ib{border:1px solid var(--line);background:var(--panel);color:var(--fg);width:28px;height:28px;border-radius:8px;cursor:pointer;font:inherit;line-height:1;flex:none}\n.ib:hover{border-color:var(--accent)} .ib.del:hover{border-color:var(--danger);color:var(--danger)}\n.btn{border:1px solid var(--line);background:var(--panel);color:var(--fg);border-radius:10px;padding:8px 12px;font:inherit;font-weight:500;cursor:pointer}\n.btn.pri{background:var(--accent);border-color:var(--accent);color:#fff} .btn:hover{border-color:var(--accent)}\n.row{display:flex;flex-wrap:wrap;gap:8px;align-items:center}\n.form{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px 14px}\n@media (max-width:560px){.form{grid-template-columns:1fr}}\nlabel.f{display:flex;flex-direction:column;gap:4px;font-size:12.5px;color:var(--muted);min-width:0}\ninput,select{font:inherit;color:var(--fg);background:var(--field);border:1px solid var(--line);border-radius:8px;padding:8px 10px;min-width:0;width:100%;box-sizing:border-box}\ninput:focus,select:focus,.btn:focus-visible,.ib:focus-visible,.room:focus-visible{outline:2px solid var(--accent);outline-offset:1px}\ninput.mono{font-family:var(--f-mono);font-size:12.5px}\n.sec{margin-top:16px;border-top:1px solid var(--line);padding-top:12px}\n.lamp{display:grid;grid-template-columns:22px minmax(0,1.4fr) minmax(0,1fr) auto;gap:6px;align-items:center;margin-bottom:6px}\n.lamp .n{color:var(--muted);font-variant-numeric:tabular-nums;text-align:right}\n@media (max-width:560px){.lamp{grid-template-columns:22px minmax(0,1fr) auto}.lamp .nm{grid-column:2}}\n.chips{display:flex;flex-wrap:wrap;gap:6px}.chip{display:inline-flex;align-items:center;gap:6px;padding:4px 6px 4px 10px;border-radius:999px;background:var(--field);border:1px solid var(--line)}\n.chip button{border:0;background:none;color:var(--muted);cursor:pointer;font:inherit;padding:0 4px}\n.hint{color:var(--muted);font-size:12.5px;line-height:1.5;margin:6px 0 0}\n.out{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:16px}@media (max-width:820px){.out{grid-template-columns:1fr}}\ntextarea{width:100%;box-sizing:border-box;min-height:180px;font-family:var(--f-mono);font-size:11.5px;background:var(--field);color:var(--fg);border:1px solid var(--line);border-radius:10px;padding:10px;resize:vertical}\nol.steps{margin:6px 0 0;padding-left:20px;color:var(--muted);line-height:1.6}\n.lock{color:var(--muted);font-size:12px}\n.toast{position:fixed;bottom:calc(16px + env(safe-area-inset-bottom,0px));left:50%;transform:translateX(-50%);background:var(--fg);color:var(--bg);padding:8px 14px;border-radius:10px;font-size:13px}\n.empty{color:var(--muted);padding:20px 0}\n.imp textarea{min-height:110px}\n.brand{display:flex;align-items:center;gap:10px}.logo{width:34px;height:34px;border-radius:10px;background:linear-gradient(145deg,#FBBF24,#D97706);display:grid;place-items:center;color:#fff;flex:none}.logo svg{width:20px;height:20px;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}\n:host([card]){height:auto;overflow:visible;background:transparent}\n.menu{font-size:16px}\n.logo2{flex:none;display:block;width:40px;height:40px}.logo2 svg{width:40px;height:40px;display:block}\nfooter{color:var(--muted);font-size:12px;text-align:center}\n.fbar{display:flex;gap:2px;overflow-x:auto;background:linear-gradient(180deg,#1C2C47,#132036);border-radius:12px;padding:6px 8px 0;scrollbar-width:thin}\n.tab{flex:none;display:flex;flex-direction:column;align-items:center;gap:3px;min-width:68px;padding:8px 10px 9px;border:0;background:none;color:rgba(255,255,255,.62);font:inherit;font-size:11.5px;cursor:pointer;border-bottom:2px solid transparent;border-radius:8px 8px 0 0}\n.tab svg{width:24px;height:24px;fill:currentColor}\n.tab:hover{color:#fff;background:rgba(255,255,255,.06)}\n.tab.sel{color:#fff;border-bottom-color:#fff}\n.tab:focus-visible{outline:2px solid var(--accent);outline-offset:-2px}\n.tab .lb{max-width:96px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.tab.add{color:rgba(255,255,255,.8)} .tab.add svg{opacity:.9}\n.fedit{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.6fr);gap:14px;margin-top:14px}\n@media (max-width:820px){.fedit{grid-template-columns:1fr}}\n.icons{display:grid;grid-template-columns:repeat(auto-fill,minmax(40px,1fr));gap:6px}\n.icons button{height:40px;border:1px solid var(--line);background:var(--field);color:var(--fg);border-radius:9px;cursor:pointer;display:grid;place-items:center;padding:0}\n.icons button svg{width:22px;height:22px;fill:currentColor}\n.icons button:hover{border-color:var(--accent)} .icons button.sel{border-color:var(--accent);background:var(--accent-soft);color:var(--accent)}\n.icons button:focus-visible{outline:2px solid var(--accent);outline-offset:1px}\n.room .ri{width:20px;height:20px;fill:var(--muted);flex:none}\n.scn{display:grid;grid-template-columns:minmax(0,1.3fr) minmax(0,1.3fr) minmax(0,.8fr) minmax(0,.8fr) minmax(0,1.4fr) auto;gap:6px 8px;align-items:end;padding:8px 0;border-bottom:1px dashed var(--line)}\n.scn:last-child{border-bottom:0}\n@media (max-width:820px){.scn{grid-template-columns:repeat(2,minmax(0,1fr))}.scn>span{grid-column:2;justify-self:end}}\ninput:disabled{opacity:.45}\n\n.sum{cursor:pointer;list-style:none}.sum::-webkit-details-marker{display:none}.sum::before{content:\"▸ \";color:var(--muted)}details[open]>.sum::before{content:\"▾ \"}\n.fgrp{margin-top:16px}.fhead{display:flex;align-items:center;gap:8px;margin-bottom:8px}.fhead svg{width:22px;height:22px;fill:var(--accent)}\n.acards{display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:10px}\n.acard{background:var(--field);border:1px solid var(--line);border-radius:12px;padding:10px;display:flex;flex-direction:column;gap:8px;min-width:0}\n.ahead{display:flex;align-items:center;justify-content:space-between;gap:8px}.ahead b{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.ahead select{width:auto;max-width:55%;padding:4px 8px;font-size:12.5px}\n.lights{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:6px}\n.lights li{display:grid;grid-template-columns:22px minmax(0,1fr) minmax(0,.9fr) 28px;gap:6px;align-items:center}\n.lights select,.acard>select{padding:4px 8px;font-size:12.5px}\n.ln{min-width:0}.ln b{display:block;font-weight:500;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.ln small{display:block;color:var(--muted);font-family:var(--f-mono);font-size:11px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.chk{display:inline-flex;align-items:center;gap:6px;color:var(--muted);font-size:13px}.chk input{width:auto}\n\n/* Kachel-Design */\n.pv .pg{display:block}\n.pgr{display:flex;align-items:center;gap:10px}.pgr2{display:flex;align-items:center;justify-content:space-between;gap:8px;padding-left:46px;margin-top:6px;min-height:8px}\n.pv .pg.nof{background:none;border-color:transparent}\n.pbar{display:block;height:6px;border-radius:3px;background:rgba(255,255,255,.18);margin-top:6px;overflow:hidden}.pbar i{display:block;height:100%;background:#FFA94D}\n.ptune{display:grid;place-items:center;width:36px}.ptune svg{width:22px;height:22px;fill:#fff;opacity:.85}\n.pchev{font-size:18px;line-height:1;opacity:.9;margin-left:auto}\n.pdot{display:inline-grid;place-items:center;flex:none}.pdot svg{width:100%;height:100%;fill:currentColor}\n.prow{margin:0 0 8px 6px}\n.pl.v{flex-direction:column;text-align:center;align-items:center}\n.pbadge{float:right;font-size:10.5px;color:rgba(255,255,255,.7);border:1px solid rgba(255,255,255,.25);border-radius:6px;padding:1px 6px}\n.seg{display:inline-flex;border:1px solid var(--line);border-radius:10px;overflow:hidden}.seg button{border:0;background:var(--panel);color:var(--fg);padding:7px 12px;font:inherit;cursor:pointer}.seg button+button{border-left:1px solid var(--line)}.seg button.on{background:var(--accent);color:#fff}\n.dgrid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:10px 18px}\n.dgrid .chk{display:flex;margin:5px 0;color:var(--fg)}.dgrid label.f{margin:6px 0}\n.dh3{font-size:12.5px;font-weight:600;margin:8px 0 6px;color:var(--fg)}\n.own{color:var(--accent);font-size:11px;font-weight:600}\n.ord{display:flex;flex-direction:column;gap:4px;margin-bottom:8px}.oi{display:flex;align-items:center;gap:6px;padding:4px 8px 4px 2px;border:1px solid var(--line);border-radius:8px;background:var(--field)}\n.ricons{display:flex;flex-wrap:wrap;gap:5px}.ricons button{width:36px;height:36px;border:1px solid var(--line);background:var(--field);color:var(--fg);border-radius:9px;cursor:pointer;display:grid;place-items:center;padding:0}\n.ricons button svg{width:20px;height:20px;fill:currentColor}.ricons button ha-icon{--mdc-icon-size:20px}.ricons button.sel{border-color:var(--accent);background:var(--accent-soft);color:var(--accent)}\n.pdel{border:0;background:none;color:rgba(255,255,255,.55);cursor:pointer;font:inherit;font-size:13px;padding:2px 4px;border-radius:6px;flex:none}.pdel:hover{color:#fff;background:rgba(220,60,60,.5)}\n\n.psm{display:inline-flex;align-items:center;gap:6px;margin:0 0 10px;padding:4px 10px 4px 6px;border-radius:16px;background:rgba(255,255,255,.1);border:1px solid rgba(255,255,255,.2);font-size:12.5px;cursor:pointer}\n.smk{display:flex;flex-direction:column;gap:8px}.smr{display:grid;grid-template-columns:70px 30px minmax(0,1.2fr) 70px minmax(0,1.4fr);gap:8px;align-items:end}\n.smr b{font-weight:600;font-size:12.5px;align-self:center}.smi{display:grid;place-items:center;height:36px;border-radius:8px;background:#1C2C47}\n.smr input[type=color]{padding:2px;height:36px;cursor:pointer}\n@media (max-width:640px){.smr{grid-template-columns:60px 30px minmax(0,1fr)}.smr label:nth-of-type(2){grid-column:2/4}.smr label:nth-of-type(3){grid-column:1/-1}}\n\n.pv{position:relative;isolation:isolate}.pvbg{position:absolute;inset:0;border-radius:inherit;z-index:-1;pointer-events:none}\n.shd{padding:8px 10px;border:1px dashed var(--line);border-radius:10px;margin:4px 0}.rng{display:flex;align-items:center;gap:8px}.rng input{flex:1;padding:0;accent-color:var(--accent)}.rng output{min-width:46px;text-align:right;color:var(--fg);font-variant-numeric:tabular-nums}\n.ha2{margin-top:12px;padding-top:12px;border-top:1px solid var(--line)}\n\n/* Ziehen & Ablegen */\n.grip{touch-action:none;cursor:grab;border:0;background:none;color:var(--muted);width:22px;height:28px;padding:0;font:inherit;font-size:16px;line-height:1;flex:none;border-radius:6px;user-select:none;-webkit-user-select:none}\n.grip:hover{color:var(--fg);background:var(--line)}.grip:focus-visible{outline:2px solid var(--accent);outline-offset:1px}\n.dh{user-select:none;-webkit-user-select:none}.tab.sel{touch-action:none;cursor:grab}\n.dnd,.dnd *{cursor:grabbing!important}\n.dragging{opacity:.35}\n.ghost{position:fixed;z-index:1000;pointer-events:none;opacity:.94;box-shadow:0 14px 34px rgba(0,0,0,.28);border-radius:12px;overflow:hidden;background:var(--panel)}\n.ghost.pv{background:#1C2C47}\n.ins-before{box-shadow:0 -3px 0 var(--accent)!important}.ins-after{box-shadow:0 3px 0 var(--accent)!important}\n[data-axis=x]>.ins-before{box-shadow:-3px 0 0 var(--accent)!important}[data-axis=x]>.ins-after{box-shadow:3px 0 0 var(--accent)!important}\n.drop-ok{outline:2px dashed var(--accent)!important;outline-offset:2px}\n.fbar .drop-ok{outline-color:#fff!important;outline-offset:-3px}\n/* Vorschau */\n.pv{background:linear-gradient(160deg,#1C2C47,#0C1018);border-radius:16px;padding:14px;color:#fff;margin:0 0 16px}\n.pv .ph small{color:rgba(255,255,255,.55);font-size:11px;letter-spacing:1px;text-transform:uppercase}\n.pv h3{margin:4px 0 0;font-size:20px;font-weight:500;cursor:pointer}\n.pv .ps{color:rgba(255,255,255,.72);font-size:13px;margin:2px 0 10px;min-height:4px;cursor:pointer}\n.pv .pg{display:flex;align-items:center;gap:10px;padding:10px 12px;border-radius:18px;background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.14);cursor:pointer}\n.pv .pg.on{background:linear-gradient(160deg,rgba(255,190,90,.5),rgba(255,190,90,.15));border-color:rgba(255,190,90,.75)}\n.pv .pg b{display:block;font-weight:600}\n.pi{width:36px;height:36px;border-radius:11px;display:grid;place-items:center;background:rgba(255,255,255,.12);flex:none;color:#fff}\n.on>.pi{background:linear-gradient(145deg,#FBBF24,#F59E0B)}\n.pi svg{width:20px;height:20px;fill:#fff}.pi ha-icon{--mdc-icon-size:20px}\n.pd{display:flex;gap:4px;flex-wrap:wrap;margin-top:5px}.pd i{width:9px;height:9px;border-radius:50%;border:1.5px solid #fff;display:inline-block;box-sizing:border-box}.pd i.on{background:#FBBF24;border-color:#FBBF24}\n.pc{display:flex;flex-wrap:wrap;gap:6px;justify-content:center;margin:10px 0 0}\n.pc span{padding:6px 12px;border-radius:18px;background:rgba(255,255,255,.1);border:1px solid rgba(255,255,255,.22);font-size:13px;cursor:pointer;color:#fff}\n.pv-lamps{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;margin-top:10px}\n@media (max-width:400px){.pv-lamps{grid-template-columns:1fr}}\n.pl{display:flex;align-items:center;gap:8px;padding:8px;border-radius:14px;background:rgba(255,255,255,.07);border:1px solid rgba(255,255,255,.12);min-width:0;cursor:pointer;color:#fff}\n.pl b{font-weight:500;font-size:13px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;display:block}.pl small{color:rgba(255,255,255,.62);font-size:11.5px;display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.pl .grip{color:rgba(255,255,255,.6)}.pl .grip:hover{background:rgba(255,255,255,.12);color:#fff}\n\n/* Umbenennen */\n.ahead .aname,.fhead .aname{font:inherit;font-weight:600;color:var(--fg);background:transparent;border:1px solid transparent;border-radius:7px;padding:3px 6px;margin-left:-6px;width:auto;min-width:0;flex:1}\n.fhead .aname{flex:0 1 auto;field-sizing:content;min-width:60px;max-width:260px}\n.pen{color:var(--muted);font-size:13px;margin-left:-6px;pointer-events:none}.ahead .pen{margin-right:auto}\n.ahead .aname:hover,.fhead .aname:hover{border-color:var(--line)}.ahead .aname:focus,.fhead .aname:focus{background:var(--panel);border-color:var(--accent)}\n";
const HTML="<datalist id=\"e-light\"></datalist><datalist id=\"e-temp\"></datalist><datalist id=\"e-hum\"></datalist><datalist id=\"e-smoke\"></datalist><datalist id=\"e-scene\"></datalist><datalist id=\"e-mdi\"></datalist>\n<div class=\"wrap\">\n<header>\n  <div class=\"brand\"><span class=\"logo2\"><svg aria-hidden=\"true\" viewBox=\"0 0 512 512\"><defs><linearGradient id=\"hhg\" x1=\"0\" y1=\"0\" x2=\"0.35\" y2=\"1\"><stop offset=\"0\" stop-color=\"#FCD34D\"/><stop offset=\".55\" stop-color=\"#F59E0B\"/><stop offset=\"1\" stop-color=\"#C2410C\"/></linearGradient><radialGradient id=\"hhglow\" cx=\".5\" cy=\".5\" r=\".5\"><stop offset=\"0\" stop-color=\"#FFF7D6\"/><stop offset=\".55\" stop-color=\"#FFF1B8\" stop-opacity=\".55\"/><stop offset=\"1\" stop-color=\"#FFF1B8\" stop-opacity=\"0\"/></radialGradient></defs><path d=\"M256 30 L482 228 Q494 240 478 244 L446 244 L446 452 Q446 494 404 494 L108 494 Q66 494 66 452 L66 244 L34 244 Q18 240 30 228 Z\" fill=\"url(#hhg)\" stroke=\"url(#hhg)\" stroke-width=\"24\" stroke-linejoin=\"round\"/><path d=\"M256 30 L482 228 Q494 240 478 244 L446 244 L446 270 L66 270 L66 244 L34 244 Q18 240 30 228 Z\" fill=\"#fff\" opacity=\".12\"/><rect x=\"122\" y=\"268\" width=\"268\" height=\"56\" rx=\"18\" fill=\"#fff\" opacity=\".92\"/><rect x=\"122\" y=\"346\" width=\"268\" height=\"56\" rx=\"18\" fill=\"#fff\" opacity=\".72\"/><circle cx=\"184\" cy=\"448\" r=\"40\" fill=\"url(#hhglow)\"/><circle cx=\"256\" cy=\"448\" r=\"40\" fill=\"url(#hhglow)\"/><circle cx=\"184\" cy=\"448\" r=\"17\" fill=\"#fff\"/><circle cx=\"256\" cy=\"448\" r=\"17\" fill=\"#fff\"/><circle cx=\"328\" cy=\"448\" r=\"14\" fill=\"none\" stroke=\"#fff\" stroke-width=\"6\"/><circle cx=\"256\" cy=\"168\" r=\"30\" fill=\"#fff\" opacity=\".95\"/></svg></span>\n  <div><h1>H0walD Home</h1><p class=\"sub\">Dashboard-Editor für Home Assistant: Geschosse, Räume, Lampen, Fühler, Brandmelder und Szenen pflegen.</p></div></div>\n  <div class=\"row\"><button class=\"ib menu\" id=\"menu\" aria-label=\"Menü\" hidden>☰</button><button class=\"btn\" id=\"exp\">Daten kopieren</button><label class=\"btn\" for=\"imp\">Daten laden (.json)</label><input type=\"file\" id=\"imp\" accept=\".json,application/json\" hidden><button class=\"btn\" id=\"reset\">Beispiel laden</button></div>\n</header>\n<section class=\"panel\" id=\"haBox\" hidden>\n  <h2>1 · Aus Home Assistant</h2>\n  <div class=\"row\"><label class=\"f\" style=\"flex-direction:row;align-items:center;gap:8px\">Dashboard<select id=\"haDash\" style=\"width:auto;min-width:180px\"></select></label>\n   <button class=\"btn pri\" id=\"haLoad\">Dashboard laden</button><button class=\"btn\" id=\"haAreas\">Geschosse &amp; Bereiche übernehmen</button></div>\n  <p class=\"hint\" id=\"haInfo\">„Dashboard laden“ holt dein bestehendes Dashboard. „Geschosse &amp; Bereiche übernehmen“ legt aus deinen HA-Bereichen Geschosse und Räume mit Lampen, Fühlern und Brandmeldern an. Vorhandene Räume werden nur ergänzt.</p>\n  <div class=\"ha2\"><div class=\"row\"><label class=\"f\" style=\"flex-direction:row;align-items:center;gap:8px\">Wer sieht das Dashboard?<select id=\"visMode\" style=\"width:auto\"><option value=\"\">unverändert lassen</option><option value=\"all\">Alle Benutzer</option><option value=\"admin\">Nur Administratoren</option><option value=\"users\">Ausgewählte Benutzer</option></select></label><span class=\"row\" id=\"visUsers\" hidden></span></div>\n  <p class=\"hint\">Wird beim Speichern übernommen. „Ausgewählte Benutzer“ blendet die Geschoss-Ansichten für alle anderen aus.</p></div>\n  <details class=\"ha2\" id=\"newDash\"><summary class=\"sum\"><b>Neues Dashboard mit Helfern erstellen</b></summary>\n  <div class=\"row\" style=\"margin-top:8px\"><input id=\"ndTitle\" placeholder=\"Name, z. B. Zuhause\" style=\"max-width:220px\" autocomplete=\"off\"><input id=\"ndIcon\" class=\"mono\" value=\"mdi:home\" style=\"max-width:170px\" aria-label=\"Symbol\" spellcheck=\"false\"><label class=\"chk\"><input type=\"checkbox\" id=\"ndSide\" checked> In der Seitenleiste zeigen</label><button class=\"btn pri\" id=\"ndGo\">Dashboard erstellen</button></div>\n  <p class=\"hint\">Legt ein neues Dashboard an, übernimmt Geschosse und Bereiche (falls noch keine Räume da sind), erstellt die fehlenden Schalter-Helfer und speichert alles. Wer es sehen darf, stellst du darüber ein.</p></details>\n</section>\n<section class=\"panel\" id=\"areaBox\" hidden>\n  <details id=\"areaDet\"><summary class=\"sum\"><h2 style=\"display:inline;margin:0\">HA-Bereiche, Lampen &amp; Geschosse verwalten</h2></summary>\n  <p class=\"hint\">Änderungen werden sofort in Home Assistant gespeichert. Namen von Bereichen und Geschossen zum Umbenennen anklicken. Lampen am ⠿ in einen anderen Bereich ziehen oder über die Auswahl verschieben. Verschobene Lampen wandern im Editor automatisch in den passenden Raum.</p>\n  <div id=\"areaMgr\"><p class=\"hint\">Lädt …</p></div></details>\n</section>\n<section class=\"panel imp\" id=\"pasteBox\">\n  <h2>1 · Eigenes Dashboard einlesen (optional)</h2>\n  <p class=\"hint\" style=\"margin:0 0 8px\">Dashboard → Stift → ⋮ → <b>Raw-Konfigurationseditor</b> → alles kopieren und hier einfügen. Jede Ansicht wird zu einem Geschoss. Ohne Einlesen startest du mit einem Beispiel.</p>\n  <textarea id=\"raw\" placeholder=\"title: Zuhause&#10;views:&#10;  - title: …\" spellcheck=\"false\" aria-label=\"Raw-Konfiguration\"></textarea>\n  <div class=\"row\" style=\"margin-top:8px\"><button class=\"btn pri\" id=\"read\">Einlesen</button><span class=\"hint\" id=\"readInfo\" style=\"margin:0\"></span></div>\n</section>\n<section class=\"panel\">\n  <h2>2 · Geschosse</h2>\n  <nav class=\"fbar\" id=\"fbar\" data-axis=\"x\" role=\"tablist\" aria-label=\"Geschosse\"></nav>\n  <div id=\"fedit\"></div>\n</section>\n<div class=\"grid\">\n  <section class=\"panel\"><h2 id=\"roomsH\">3 · Räume</h2><div class=\"rooms\" id=\"rooms\"></div><div class=\"row\" style=\"margin-top:10px\" id=\"addRow\"><button class=\"btn pri\" id=\"add\">+ Neuer Raum</button></div>\n  <p class=\"hint\">Reihenfolge = Reihenfolge im Dashboard. Mit ⠿ ziehen zum Sortieren. Einen Raum auf ein Geschoss oben ziehen verschiebt ihn dorthin. Lampen auf einen Raum ziehen verschiebt sie, Szenen werden in den Raum kopiert.</p></section>\n  <section class=\"panel\" id=\"ed\"></section>\n</div>\n<section class=\"panel\">\n  <h2>4 · Code für Home Assistant</h2>\n  <div class=\"row haAct\" id=\"haAct\" hidden><button class=\"btn pri\" id=\"haSave\">Im Dashboard speichern</button><button class=\"btn\" id=\"haHelp\">Fehlende Helfer anlegen</button><button class=\"btn\" id=\"haBak\" hidden>Sicherung herunterladen</button><label class=\"chk\"><input type=\"checkbox\" id=\"haTab\"> Editor als Tab im Dashboard</label><span class=\"hint\" id=\"haSaveInfo\" style=\"margin:0\"></span></div>\n  <div class=\"out\">\n    <div><div class=\"row\" style=\"justify-content:space-between\"><b>Dashboard (Raw-Konfiguration)</b><button class=\"btn\" id=\"c1\">Kopieren</button></div>\n      <textarea id=\"o1\" readonly spellcheck=\"false\"></textarea>\n      <ol class=\"steps\"><li>Dashboard → Stift → ⋮ → <b>Raw-Konfigurationseditor</b></li><li>Vorher den alten Inhalt als Sicherung kopieren</li><li>Alles ersetzen → Speichern</li></ol></div>\n    <div><div class=\"row\" style=\"justify-content:space-between\"><b>Schalter-Helfer (configuration.yaml)</b><button class=\"btn\" id=\"c2\">Kopieren</button></div>\n      <textarea id=\"o2\" readonly spellcheck=\"false\" style=\"min-height:120px\"></textarea>\n      <ol class=\"steps\"><li>File editor → <code>configuration.yaml</code></li><li>Diese Zeile ganz unten einfügen, ganz links (gibt es schon eine Zeile <code>input_boolean:</code>, diese ersetzen)</li><li>Entwicklerwerkzeuge → YAML → Konfiguration prüfen → <b>Input-Booleans</b> neu laden</li></ol>\n      <p class=\"hint\" id=\"dupWarn\" style=\"color:var(--danger)\" hidden></p>\n      <p class=\"hint\">Braucht in Home Assistant: <b>Mushroom</b> und <b>card-mod</b> (beide über HACS).</p></div>\n  </div>\n</section>\n<footer>H0walD Home · MIT-Lizenz · Läuft komplett im Browser, es werden keine Daten verschickt.</footer>\n</div>\n<div class=\"toast\" id=\"toast\" hidden></div>\n";
