 const ic=E.dotIcon==='bulb'?`{{ 'mdi:lightbulb' if ${on} else 'mdi:lightbulb-outline' }}`:E.dotIcon==='lamp'?(l.icon||`{{ state_attr('${e}','icon') or 'mdi:lightbulb' }}`):`{{ 'mdi:circle' if ${on} else 'mdi:circle-outline' }}`;
