 const scenes=E.showScenes&&r.scenes?JSON.parse(JSON.stringify(r.scenes).replace(new RegExp(reEsc(r.origGroup||TG)+'(?![a-z0-9_])','g'),grp)):null;if(scenes)scenes.alignment=E.sceneAlign==='start'?'start':'center';
